insert into public.movies (id, branch_id, title, search_query, release_year, story_year, media_type, importance, note, why, poster_path, active, display_order)
values
  ('i01', 'infinito', 'Homem de Ferro', 'Iron Man', 2008, 2010, 'movie', 'recomendado', null, 'Onde tudo começa. Apresenta Tony Stark e a ideia de herói público e falível — e traz a primeira cena pós-créditos que inventou o conceito de universo compartilhado no cinema.', '/mqN7RxojEiPoh3FTSTwOtwg7KAu.jpg', true, 1),
  ('i02', 'infinito', 'O Incrível Hulk', 'The Incredible Hulk', 2008, 2011.1, 'movie', 'completista', null, 'Apresenta Bruce Banner e, mais importante, o General Ross — um personagem secundário aqui que se torna peça central décadas depois na linha do Capitão América.', '/v1UXe9WlwkkZ5YrffUSPdYNeJz3.jpg', true, 2),
  ('i03', 'infinito', 'Homem de Ferro 2', 'Iron Man 2', 2010, 2011, 'movie', 'completista', null, 'Expande a S.H.I.E.L.D. de organização misteriosa para peça central, e apresenta Natasha Romanoff e o Máquina de Combate.', '/vzROjQbgKWMVf2EldXipCcjpuBL.jpg', true, 3),
  ('i04', 'infinito', 'Thor', 'Thor', 2011, 2011.2, 'movie', 'recomendado', null, 'Abre a porta do lado cósmico e mitológico do universo. Apresenta Asgard e, sobretudo, Loki — o personagem que mais tarde se torna a chave de todo o multiverso.', '/aEV9QmgBqjRTdjsvdCgdK89tavQ.jpg', true, 4),
  ('i05', 'infinito', 'Capitão América: O Primeiro Vingador', 'Captain America: The First Avenger', 2011, 1943, 'movie', 'recomendado', null, 'O primeiro ponto da cronologia, lá nos anos 40. Estabelece o Capitão América, o Tesseract e a origem histórica que sustenta boa parte da saga.', '/19wxfSXHhuJBRbbfUweCsfXFhpv.jpg', true, 5),
  ('i06', 'infinito', 'Os Vingadores', 'The Avengers', 2012, 2012, 'movie', 'essencial', null, 'O time se forma. É o filme que provou que crossover funciona e criou o modelo que o Doomsday leva ao extremo — só que com três universos em vez de um.', '/PtSapjHdDjlVcsqdEo0u7rDE6i.jpg', true, 6),
  ('i07', 'infinito', 'Homem de Ferro 3', 'Iron Man 3', 2013, 2012.5, 'movie', 'completista', null, 'Mostra Tony lidando com as consequências psicológicas de ser herói, e apresenta uma organização e um vilão cuja verdadeira história é retomada anos depois em Shang-Chi.', '/C7MZwRTjvEy7gkWcLJeBGZFE1w.jpg', true, 7),
  ('i08', 'infinito', 'Thor: O Mundo Sombrio', 'Thor: The Dark World', 2013, 2013, 'movie', 'completista', null, 'Apresenta o Éter, uma das Joias do Infinito, e aprofunda a mitologia asgardiana que Ragnarok depois vira do avesso.', '/9qdqXIx2neypuT1kWKCTI2vsO4q.jpg', true, 8),
  ('i09', 'infinito', 'Capitão América: O Soldado Invernal', 'Captain America: The Winter Soldier', 2014, 2014, 'movie', 'recomendado', null, 'O filme que reorganiza o tabuleiro político do universo inteiro. Aprofunda Bucky e Sam Wilson, os dois personagens que herdam o legado do Capitão.', '/9sTDXtIIfHza1rAbmHU2djyzEXA.jpg', true, 9),
  ('i10', 'infinito', 'Guardiões da Galáxia', 'Guardians of the Galaxy', 2014, 2014.3, 'movie', 'recomendado', null, 'Abre o espaço sideral do universo. Apresenta as Joias do Infinito como conceito unificado e coloca Thanos em cena como ameaça de fundo.', '/xaY92XMToaSnBuvCui3LHzNGqZB.jpg', true, 10),
  ('i11', 'infinito', 'Vingadores: Era de Ultron', 'Avengers: Age of Ultron', 2015, 2015, 'movie', 'essencial', null, 'Nascem Wanda Maximoff e o Visão, e surge a fratura de confiança entre Stark e Rogers que estoura em Guerra Civil.', '/uvzqTsRmUzk9mJVzX8cMSWMyM5l.jpg', true, 11),
  ('i12', 'infinito', 'Homem-Formiga', 'Ant-Man', 2015, 2015.5, 'movie', 'recomendado', null, 'Apresenta o Reino Quântico — que parece um detalhe divertido aqui e vira o mecanismo central do multiverso e das viagens no tempo.', '/lsiy4IcnbtChkayPMxLda2fq4xM.jpg', true, 12),
  ('i13', 'infinito', 'Capitão América: Guerra Civil', 'Captain America: Civil War', 2016, 2016, 'movie', 'essencial', null, 'Racha os Vingadores em dois lados. Apresenta o Pantera Negra e a versão do Homem-Aranha que segue até hoje no MCU.', '/dsvUR5aEVSkB1Sro7nT6Khqik71.jpg', true, 13),
  ('i14', 'infinito', 'Doutor Estranho', 'Doctor Strange', 2016, 2016.9, 'movie', 'essencial', null, 'Apresenta a magia, as dimensões paralelas e a Joia do Tempo. É a base conceitual direta de tudo que o multiverso faz depois.', '/pb4clPWRJ5AKlSFu1HrrHdt5uAw.jpg', true, 14),
  ('i15', 'infinito', 'Guardiões da Galáxia Vol. 2', 'Guardians of the Galaxy Vol. 2', 2017, 2014.6, 'movie', 'completista', null, 'Aprofunda os laços da família Guardiões e planta sementes cósmicas — inclusive Adam Warlock — colhidas nos filmes seguintes.', '/jGtBLu0JAKf5JxhWgmF68HROzCA.jpg', true, 15),
  ('i16', 'infinito', 'Homem-Aranha: De Volta ao Lar', 'Spider-Man: Homecoming', 2017, 2016.7, 'movie', 'recomendado', null, 'Define quem é o Peter Parker desse universo: um garoto sob a mentoria de Tony Stark, o que dá peso emocional a tudo que vem depois.', '/1nkwRL17cAGO8A1yu3miRBdvOsl.jpg', true, 16),
  ('i17', 'infinito', 'Thor: Ragnarok', 'Thor: Ragnarok', 2017, 2017.5, 'movie', 'essencial', null, 'Transforma o tom e a trajetória de Thor por completo, e o estado em que ele termina o filme é literalmente o ponto de partida de Guerra Infinita.', '/2K45Fp6koAVoeeYS6aMb9BeNt4F.jpg', true, 17),
  ('i18', 'infinito', 'Pantera Negra', 'Black Panther', 2018, 2016.5, 'movie', 'essencial', null, 'Apresenta Wakanda e o vibranium. Essencial para o Doomsday: os wakandanos são uma das cinco frentes confirmadas no filme.', '/ubXNpxL2ASSzY0f8Hxv08pOsV2L.jpg', true, 18),
  ('i19', 'infinito', 'Vingadores: Guerra Infinita', 'Avengers: Infinity War', 2018, 2018.2, 'movie', 'essencial', null, 'O ponto de virada da Saga do Infinito, com todos os fios se encontrando. Nada do que vem depois faz sentido sem ele.', '/A4kvp7vY1BDLrrQIagRCffLKj1t.jpg', true, 19),
  ('i20', 'infinito', 'Homem-Formiga e a Vespa', 'Ant-Man and the Wasp', 2018, 2018, 'movie', 'completista', null, 'Estabelece as regras do Reino Quântico com seriedade e apresenta personagens que voltam com papel muito maior em Quantumania.', '/5BKRuGVxx8qsB7WGSJ0oWRCHsgN.jpg', true, 20),
  ('i21', 'infinito', 'Capitã Marvel', 'Captain Marvel', 2019, 1995, 'movie', 'recomendado', null, 'Origem nos anos 90 que explica a tecnologia por trás dos Vingadores, apresenta os Skrulls (retomados em Invasão Secreta) e a heroína mais poderosa do time.', '/n3BisLdTMceUWcdP1ooP5VwN9JF.jpg', true, 21),
  ('i22', 'infinito', 'Vingadores: Ultimato', 'Avengers: Endgame', 2019, 2023, 'movie', 'essencial', null, 'Fecha a Saga do Infinito — e o método usado pelos heróis é exatamente o que bagunça as linhas temporais e abre caminho para o multiverso.', '/9fRX8UKlIW7Lb9GqNsJVakWWFCi.jpg', true, 22),
  ('i23', 'infinito', 'Homem-Aranha: Longe de Casa', 'Spider-Man: Far From Home', 2019, 2024, 'movie', 'recomendado', null, 'Mostra como o mundo ficou depois de Ultimato e traz a primeira menção explícita à ideia de realidades alternativas dentro do MCU.', '/tX0o4AdHpidgniTWwfzK0dNTKrc.jpg', true, 23),
  ('m01', 'multiverso', 'Viúva Negra', 'Black Widow', 2021, 2016.2, 'movie', 'completista', null, 'Preenche uma lacuna na história da Natasha e apresenta Yelena Belova — que se torna peça central dos Thunderbolts, um dos times do Doomsday.', '/lrJ9QI2HMbO8N2S2r2v7fjtou5c.jpg', true, 1),
  ('m02', 'multiverso', 'Shang-Chi e a Lenda dos Dez Anéis', 'Shang-Chi and the Legend of the Ten Rings', 2021, 2023.5, 'movie', 'essencial', null, 'Revela a verdadeira organização dos Dez Anéis e apresenta uma tecnologia de origem desconhecida que sinaliza ameaças interdimensionais.', '/d3wNegI8XJF8Kto6KhlqPicBRAp.jpg', true, 2),
  ('m03', 'multiverso', 'Eternos', 'Eternals', 2021, 2023.6, 'movie', 'recomendado', null, 'Adiciona uma camada mitológica milenar ao universo, apresentando os Celestiais — as entidades mais poderosas já mostradas — e um grupo ainda por se integrar.', '/2IgZIYa8iTQuLNIcVERwXmh8pUj.jpg', true, 3),
  ('m04', 'multiverso', 'Homem-Aranha: Sem Volta pra Casa', 'Spider-Man: No Way Home', 2021, 2024.2, 'movie', 'essencial', 'Abre o multiverso — puxa os Aranhas antigos', 'O momento em que o multiverso deixa de ser teoria e vira realidade visível. É o filme que autoriza a existência de todas as versões alternativas.', '/xaKydnMw6wR1MBAjS5seGPVusbs.jpg', true, 4),
  ('m05', 'multiverso', 'Doutor Estranho no Multiverso da Loucura', 'Doctor Strange in the Multiverse of Madness', 2022, 2024.3, 'movie', 'essencial', null, 'Estabelece as regras práticas do multiverso: como se viaja, o que são incursões e o preço de mexer nisso. Leitura obrigatória pro Doomsday.', '/7pLIVfovuIf2KQOOvMsKx3Lanrg.jpg', true, 5),
  ('m06', 'multiverso', 'Thor: Amor e Trovão', 'Thor: Love and Thunder', 2022, 2025.3, 'movie', 'recomendado', null, 'Atualiza onde Thor está emocionalmente e amplia o panteão de deuses do universo, apresentando quem manda entre eles.', '/8gdBMIYwPPxp3b9FjY9yCxme5Rs.jpg', true, 6),
  ('m07', 'multiverso', 'Pantera Negra: Wakanda Para Sempre', 'Black Panther: Wakanda Forever', 2022, 2025.6, 'movie', 'essencial', null, 'Define a nova geração de Wakanda que vai representar o país no Doomsday, e amplia o mapa político do mundo pós-Ultimato.', '/9ntIvu7tQQNpcs1JtkoG3l4mIzn.jpg', true, 7),
  ('m08', 'multiverso', 'Homem-Formiga e a Vespa: Quantumania', 'Ant-Man and the Wasp: Quantumania', 2023, 2026, 'movie', 'recomendado', null, 'Apresenta formalmente o conceito de variantes conquistadoras e o vilão que deveria comandar a saga — contexto essencial pra entender a troca pelo Doutor Destino.', '/qZDafbofrZn46MmDwJS8fCSCe6l.jpg', true, 8),
  ('m09', 'multiverso', 'Guardiões da Galáxia Vol. 3', 'Guardians of the Galaxy Vol. 3', 2023, 2026.1, 'movie', 'completista', null, 'Encerra o arco dos Guardiões atuais e deixa claro quem continua ativo no universo daqui pra frente.', '/4yycSPnchdNAZirGkmCYQwTd3cr.jpg', true, 9),
  ('m10', 'multiverso', 'As Marvels', 'The Marvels', 2023, 2026.2, 'movie', 'recomendado', null, 'Junta três heroínas de gerações diferentes e termina com um evento de ruptura no espaço-tempo que aponta direto pro futuro da saga.', '/wpp5KIwjtrKoWj5H0TSsJdqsDx7.jpg', true, 10),
  ('m11', 'multiverso', 'Deadpool & Wolverine', 'Deadpool & Wolverine', 2024, 2026.4, 'movie', 'essencial', 'Amarra a Fox/X-Men ao MCU via TVA', 'O filme que oficialmente amarra o universo da Fox ao MCU através da TVA. Sem ele, a presença dos X-Men originais no Doomsday não se sustenta.', '/cJFqqiDYprqExaXatu4AaoMzDG2.jpg', true, 11),
  ('m12', 'multiverso', 'Capitão América: Admirável Mundo Novo', 'Captain America: Brave New World', 2025, 2026.6, 'movie', 'essencial', null, 'Apresenta Sam Wilson consolidado como Capitão América e coloca o General Ross num novo lugar de poder — com implicações diretas na política do universo.', '/5nbSgP8f5LMCI0PwVRRaHJaUmR3.jpg', true, 12),
  ('m13', 'multiverso', 'Thunderbolts*', 'Thunderbolts', 2025, 2026.7, 'movie', 'essencial', 'Nascem os Novos Vingadores', 'O filme onde nasce o time dos Novos Vingadores, uma das frentes confirmadas do Doomsday. Praticamente um prólogo.', '/3cME244QKWg5mAvcsmthmtx7VR1.jpg', true, 13),
  ('m14', 'multiverso', 'Quarteto Fantástico: Primeiros Passos', 'The Fantastic Four: First Steps', 2025, 2026.8, 'movie', 'essencial', null, 'Apresenta o Quarteto Fantástico e o Doutor Destino, o vilão do Doomsday. Talvez o filme mais indispensável de todos os recentes.', '/8F2vIxWycANHW763lnx2hJVtjDC.jpg', true, 14),
  ('m15', 'multiverso', 'Homem-Aranha: Um Novo Dia', 'Spider-Man: Brand New Day', 2026, 2026.9, 'movie', 'essencial', 'Último filme antes do Doomsday', 'O último filme antes do Doomsday. Fecha os fios pendentes do Homem-Aranha e serve de ponte imediata para o crossover.', '/x0nvYzQpyJc5pdT9lMnkMuYAg0O.jpg', true, 15),
  ('s01', 'series', 'WandaVision', 'WandaVision', 2021, 2023.2, 'tv', 'essencial', 'Prepara o Multiverso da Loucura', 'Aprofunda Wanda depois das perdas que sofreu e apresenta a Feitiçaria do Caos, o poder que motiva o Multiverso da Loucura.', '/8mAyDNSCZDiejPTm4lwgbztut7y.jpg', true, 1),
  ('s02', 'series', 'Falcão e o Soldado Invernal', 'The Falcon and the Winter Soldier', 2021, 2023.3, 'tv', 'recomendado', null, 'A transição do escudo. Explica por que Sam aceita o manto e o custo político dessa escolha — base do novo Capitão América.', '/oF9njYCN6lBdrsi6wfulcxTggvn.jpg', true, 2),
  ('s03', 'series', 'Loki — 1ª temporada', 'Loki', 2021, 2023.1, 'tv', 'essencial', 'TVA + multiverso: espinha dorsal', 'A espinha dorsal do multiverso. Apresenta a TVA, a Linha do Tempo Sagrada e quem realmente estava no controle dela. Indispensável.', '/2TwPJfPiBI2lVrofggw3H0b4cDC.jpg', true, 3),
  ('s04', 'series', 'What If…? — 1ª temporada', 'What If', 2021, 2023.12, 'tv', 'recomendado', null, 'Mostra na prática como pequenas mudanças criam realidades inteiramente diferentes, e apresenta o Vigia, observador de todo o multiverso.', '/kJQWrrwtu0TAsIKq8Adgzeg4bFt.jpg', true, 4),
  ('s05', 'series', 'Gavião Arqueiro', 'Hawkeye', 2021, 2024.9, 'tv', 'completista', null, 'Apresenta Kate Bishop e devolve ao universo um vilão do submundo de Nova York que reaparece com muito mais peso depois.', '/yPRl1dvc0FHi8Syy1XhsoMumw9J.jpg', true, 5),
  ('s06', 'series', 'Cavaleiro da Lua', 'Moon Knight', 2022, 2025, 'tv', 'completista', null, 'Expande o universo pro terreno sobrenatural e o panteão egípcio, mostrando que existem forças fora do alcance dos Vingadores.', '/tkc7AVyUoG9VEeDvukN0TVqa24C.jpg', true, 6),
  ('s07', 'series', 'Ms. Marvel', 'Ms. Marvel', 2022, 2025.2, 'tv', 'recomendado', 'Liga direto a As Marvels', 'Apresenta Kamala Khan e a natureza dos poderes dela — uma revelação que abre a porta para os mutantes dentro do MCU.', '/8Rzkt43GnMyTN0srvn3Z4u7C7VU.jpg', true, 7),
  ('s08', 'series', 'Mulher-Hulk: Defensora de Heróis', 'She-Hulk: Attorney at Law', 2022, 2025.4, 'tv', 'completista', null, 'Brinca com as próprias regras do universo e traz de volta o Demolidor num tom novo, preparando terreno pra fase seguinte dele.', '/5o8Nw4mBCqyO5dtfpPAZXjv5XJ2.jpg', true, 8),
  ('s09', 'series', 'Lobisomem na Noite', 'Werewolf by Night', 2022, 2025.5, 'movie', 'completista', null, 'Curto e fácil de encaixar. Apresenta o canto sobrenatural do universo e monstros que ampliam o tipo de ameaça possível.', '/N9jyoeH3wKhiHYNYLE9Pnnls9D.jpg', true, 9),
  ('s10', 'series', 'Invasão Secreta', 'Secret Invasion', 2023, 2025.8, 'tv', 'completista', null, 'Retoma os Skrulls apresentados em Capitã Marvel e muda de forma permanente a posição de Nick Fury no tabuleiro.', '/2jTlRJxmulcKSedMx3c9Hp3frDY.jpg', true, 10),
  ('s11', 'series', 'Loki — 2ª temporada', 'Loki', 2023, 2023.15, 'tv', 'essencial', 'Fecha o arco da TVA', 'Onde o multiverso é definitivamente liberado. A situação em que essa temporada termina é literalmente a premissa do Doomsday.', null, true, 11),
  ('s12', 'series', 'What If…? — 2ª temporada', 'What If', 2023, 2023.17, 'tv', 'completista', null, 'Mais variações do multiverso, agora cruzando personagens de épocas diferentes — reforça o quanto as realidades já estão embaralhadas.', '/a87nXpE9vz8AE7qOxy0oaulEIpW.jpg', true, 12),
  ('s13', 'series', 'Echo', 'Echo', 2024, 2025.7, 'tv', 'completista', null, 'Aprofunda uma personagem do submundo e conecta diretamente com o retorno do Demolidor.', '/6Khp1QR8IsRBCfMxeMoDNAxPEL4.jpg', true, 13),
  ('s14', 'series', 'Agatha Desde Sempre', 'Agatha All Along', 2024, 2026.3, 'tv', 'completista', null, 'Continua o fio da bruxaria deixado por WandaVision e amplia as regras da magia no universo.', '/4TnWiIc9VFqX1HKU4HJ8vNWKHvX.jpg', true, 14),
  ('s15', 'series', 'What If…? — 3ª temporada', 'What If', 2024, 2023.18, 'tv', 'completista', null, 'Fecha a antologia de realidades alternativas, com o multiverso já plenamente estabelecido no resto da saga.', '/qalQMLFNhiC2uplBfCjVMfPpQLI.jpg', true, 15),
  ('s16', 'series', 'Demolidor: Renascido', 'Daredevil: Born Again', 2025, 2026.5, 'tv', 'recomendado', null, 'Mostra o nível de rua de Nova York sob um novo equilíbrio de poder — importante pro pano de fundo em que o Homem-Aranha atual opera.', '/r5hNFtkNAauxc2G4VUlnJOaVIb0.jpg', true, 16),
  ('s17', 'series', 'Coração de Ferro (Ironheart)', 'Ironheart', 2025, 2026.65, 'tv', 'completista', null, 'Apresenta a herdeira da tecnologia Stark e cruza tecnologia com magia, um choque que o universo ainda vai explorar.', '/yRanvKZhy5NdF64amF0WNOAIuQu.jpg', true, 17),
  ('x01', 'xmen', 'X-Men', 'X-Men', 2000, 2000, 'movie', 'recomendado', null, 'O filme que iniciou a era moderna dos super-heróis no cinema. Apresenta Xavier, Magneto, Wolverine e a tensão mutante que o Doomsday resgata.', '/eTAK1gU8vTaHt0W9I6PFYQsdhKP.jpg', true, 1),
  ('x02', 'xmen', 'X-Men 2', 'X2', 2003, 2003, 'movie', 'recomendado', null, 'Aprofunda o conflito entre convivência e separatismo, e é considerado o ápice da primeira trilogia dos X-Men.', '/fbKrtVCaTBBdgwvrLiyYFsCewlK.jpg', true, 2),
  ('x03', 'xmen', 'X-Men: O Confronto Final', 'X-Men: The Last Stand', 2006, 2006, 'movie', 'recomendado', null, 'Fecha a trilogia original e apresenta a Fênix — arco que o próprio estúdio revisita anos depois.', '/rcPewUA6Lszt25wIa1nkW3A82JX.jpg', true, 3),
  ('x04', 'xmen', 'X-Men Origens: Wolverine', 'X-Men Origins: Wolverine', 2009, 1979, 'movie', 'completista', null, 'Preenche o passado do Wolverine. Opcional, mas explica de onde vem a versão do personagem que aparece em Deadpool & Wolverine.', '/a3V6xhrI4gpMv4MI5RKj9AtK3Nf.jpg', true, 4),
  ('x05', 'xmen', 'X-Men: Primeira Classe', 'X-Men: First Class', 2011, 1962, 'movie', 'recomendado', null, 'Reinicia a franquia nos anos 60 mostrando a amizade e a ruptura entre Xavier e Magneto — a raiz de todo o conflito mutante.', '/hMVzCXh2vmCMzZS2mM2QvMqQZZs.jpg', true, 5),
  ('x06', 'xmen', 'Wolverine: Imortal', 'The Wolverine', 2013, 2013.5, 'movie', 'completista', null, 'Foco no Wolverine solo, no Japão. Estabelece o estado emocional dele que Logan depois leva às últimas consequências.', '/qlQ00x9OWU8RdxaV1UtUW8X9PbY.jpg', true, 6),
  ('x07', 'xmen', 'X-Men: Dias de um Futuro Esquecido', 'X-Men: Days of Future Past', 2014, 1973, 'movie', 'essencial', 'Multiverso mutante: une as duas linhas do tempo', 'Une os dois elencos dos X-Men através de viagem no tempo — a primeira vez que essa franquia mexeu com realidades alternativas.', '/cAGrjXVQoNyqHgxPoXr68JGqmp0.jpg', true, 7),
  ('x08', 'xmen', 'Deadpool', 'Deadpool', 2016, 2016.4, 'movie', 'recomendado', null, 'Apresenta o Deadpool e a consciência dele de estar num filme, tom que o crossover com o MCU depois aproveita inteiro.', '/tekExNqal2kcHp8BKiHX5jjxK9J.jpg', true, 8),
  ('x09', 'xmen', 'X-Men: Apocalipse', 'X-Men: Apocalypse', 2016, 1983, 'movie', 'completista', null, 'Amplia a escala das ameaças mutantes e mostra a formação da geração mais jovem dos X-Men.', '/avAUyU5cXk0ASy5yR8FMtO78LRS.jpg', true, 9),
  ('x10', 'xmen', 'Logan', 'Logan', 2017, 2029, 'movie', 'recomendado', null, 'O ponto final emocional do Wolverine da Fox, num futuro sombrio. Dá o peso dramático que torna significativo o reencontro com o personagem depois.', '/f0CtZbae9cXj8bkWdCHzUHx5lsR.jpg', true, 10),
  ('x11', 'xmen', 'Deadpool 2', 'Deadpool 2', 2018, 2018.1, 'movie', 'recomendado', null, 'Apresenta a Força X e um dispositivo de manipulação temporal que, mais tarde, se revela peça importante na conexão com a TVA.', '/rDRIx1J63HVXUkjWTf4RUiNOa3D.jpg', true, 11),
  ('x12', 'xmen', 'X-Men: Fênix Negra', 'Dark Phoenix', 2019, 1992, 'movie', 'completista', null, 'Nova tentativa de adaptar a saga da Fênix; encerra o arco dos X-Men modernos da Fox.', '/w4mvEKtjawXdYaq1bORuodLX6ti.jpg', true, 12),
